test('wizard creates task planning with chosen quantities and weekly task goals',async()=>{const d=await boot({id:'task-plan'}),w=d.window,$=id=>w.document.getElementById(id);w.plannerTest.set({subjects:[{id:'a',name:'Direito',color:'#315fb3',contents:['Questões']}],stages:[]});w.document.querySelector('[data-tab="cycle"]').click();$('newPlanning').click();w.document.querySelector('[data-pw-path="simple"]').click();$('pwMeasurement').value='task';$('pwMeasurement').dispatchEvent(new w.Event('change',{bubbles:true}));$('pwNext').click();$('pwNext').click();assert.ok($('pwWeeklyTasks'));assert.equal($('pwMinimum'),null);$('pwWeeklyTasks').value='12';$('pwTaskQuantity1').value='35';const date=new Date();date.setDate(date.getDate()+30);$('pwExam').value=date.toISOString().slice(0,10);$('pwNext').click();assert.match($('planningWizardMain').textContent,/Distribuição das tarefas/);$('pwNext').click();const saved=JSON.parse(w.localStorage.getItem('ciclo-estudos-v1:cloud:task-plan'));assert.equal(saved.measurementMode,'task');assert.equal(saved.goals.weeklyTasks,12);assert.equal(saved.goals.dailyTasks,2);assert.equal(saved.stages.length,12);assert.ok(saved.stages.every(s=>s.mode==='task'));assert.ok(saved.stages.filter(s=>s.content==='Questões').every(s=>s.unit==='questões'&&s.target===35));assert.equal(saved.goals.weekly,0);w.close();});

test('replanning uses sliders summing 100 percent and updates existing plan without losing history',async()=>{const d=await boot({id:'replan'}),w=d.window,$=id=>w.document.getElementById(id);w.plannerTest.set({subjects:[{id:'a',name:'Direito',color:'#315fb3',contents:['Conteúdo novo']}],stages:[]});w.document.querySelector('[data-tab="cycle"]').click();$('newPlanning').click();w.document.querySelector('[data-pw-path="simple"]').click();$('pwNext').click();$('pwNext').click();const exam=new Date();exam.setDate(exam.getDate()+30);$('pwExam').value=exam.toISOString().slice(0,10);$('pwNext').click();let slider=w.document.querySelector('[data-ratio-slider="0"]');slider.value=65;slider.dispatchEvent(new w.Event('input',{bubbles:true}));assert.equal([...w.document.querySelectorAll('[data-pw-ratio]')].reduce((n,x)=>n+Number(x.value),0),100);$('pwNext').click();let data=()=>JSON.parse(w.localStorage.getItem('ciclo-estudos-v1:cloud:replan'));const id=data().activePlanningId;const stage=data().stages.find(s=>s.content==='Conteúdo novo');const history={id:'h',kind:'study',subjectId:'a',name:'Direito',content:stage.content,stageId:stage.id,roundId:data().roundId,planningId:id,seconds:300,countPlan:true,date:new Date().toISOString()};w.plannerTest.apply(history);w.plannerTest.configure({history:[history]});w.plannerTest.save();$('replanPlanning').click();$('pwNext').click();$('pwNext').click();assert.ok($('pwExam').value);$('pwNext').click();assert.equal($('pwNext').textContent,'Aplicar replanejamento');$('pwNext').click();assert.equal(data().activePlanningId,id);assert.equal(data().plannings.length,1);assert.equal(data().history.length,1);assert.equal(data().stages.reduce((n,s)=>n+s.done,0),300);$('deletePlanning').click();assert.equal($('deletePlanningDialog').open,true);$('confirmDeletePlanning').click();assert.equal(data().plannings.length,0);assert.equal(data().stages.length,0);assert.equal(data().history.length,1);assert.equal(data().archivedPlannings.length,1);$('restorePlanning').click();assert.equal(data().plannings.length,1);assert.equal(data().activePlanningId,id);assert.equal(data().stages.reduce((n,s)=>n+s.done,0),300);w.close();});

