test('switching proof pauses timer and restores its subject and elapsed time on return',async()=>{const d=await boot({id:'exam-timer'}),w=d.window,p=w.plannerTest,$=id=>w.document.getElementById(id);p.set({subjects:[{id:'a',name:'Direito',color:'#315fb3',contents:['Conteúdo novo']}],stages:[{id:'s',subjectId:'a',content:'Conteúdo novo',target:1800,done:0}]});const old=p.exams()[0].id;p.configure({session:{stageId:'s',elapsed:123,running:false,last:Date.now(),mode:'elapsed',phase:'work',phaseLeft:1500}});$('examTopChange').click();w.document.querySelector('[data-exam-catalog="see-df"]').click();assert.equal($('examChoiceDialog').open,false);assert.equal(p.edital().subjects.length,10);assert.equal(p.selectExam(old),true);const data=JSON.parse(w.localStorage.getItem('ciclo-estudos-v1:cloud:exam-timer'));assert.equal(data.session.elapsed,123);assert.equal(data.session.stageId,'s');assert.equal(data.session.running,false);w.close();});

function topicFixture(){return {id:'ed',subjectId:'a',name:'Direito',level:'intermediate',weight:1,ratios:[50,25,25],topics:[{id:'parent',number:'1',name:'Capítulo',done:false},{id:'known',number:'1.1',name:'Já estudado',done:true},{id:'new',number:'1.2',name:'Novo conteúdo',done:false}]}}
function topicConfig(){return {examDate:'',dailyHours:3,blockMinutes:25,minimumMinutes:20,topicHours:1,weekdays:[0,1,2,3,4,5,6],mode:'time'}}
test('topic curriculum covers all leaf topics, skips completed theory, and spaces followups after theory',async()=>{const d=await boot({id:'topic-plan'}),w=d.window,p=w.plannerTest,m=topicFixture();p.set({subjects:[{id:'a',name:'Direito',color:'#315fb3',contents:['Conteúdo novo','Questões','Resumo (Revisão)']}],stages:[]});const plan=p.buildPlan(topicConfig(),[m]);assert.equal(plan.coverage.total,2);assert.equal(plan.coverage.known,1);assert.equal(plan.coverage.pending,1);assert.ok(!plan.stages.some(s=>s.curriculum.topicId==='parent'));assert.ok(!plan.stages.some(s=>s.curriculum.topicId==='known'&&s.curriculum.phase==='theory'));for(const id of ['known','new'])assert.ok(plan.stages.some(s=>s.curriculum.topicId===id));const sched=p.schedule(plan.stages,plan.config,{fresh:true});const theory=plan.stages.filter(s=>s.curriculum.phase==='theory').at(-1),theoryDate=sched.finishes.get(theory.curriculum.key);for(const s of plan.stages.filter(s=>s.curriculum.topicId==='new'&&s.curriculum.phase!=='theory')){const delay=(new Date(sched.finishes.get(s.curriculum.key)+'T12:00:00')-new Date(theoryDate+'T12:00:00'))/86400000;assert.ok(delay>=(s.curriculum.phase==='review'?7:14));}assert.equal(plan.coverage.outsideDeadline,0);w.close();});
test('short exam deadline reports uncovered topics without silently removing them',async()=>{const d=await boot({id:'short-topics'}),w=d.window,p=w.plannerTest;p.set({subjects:[{id:'a',name:'Direito',color:'#315fb3',contents:[]}],stages:[]});const date=new Date();date.setDate(date.getDate()+2);const plan=p.buildPlan({...topicConfig(),examDate:date.toISOString().slice(0,10)},[topicFixture()]);assert.equal(plan.coverage.total,2);assert.ok(plan.coverage.outsideDeadline>0);assert.ok(plan.stages.some(s=>s.curriculum.topicId==='new'&&s.curriculum.phase==='questions'));w.close();});
test('actual theory completion delays practice and records credit to exact topic block',async()=>{const d=await boot({id:'actual-topics'}),w=d.window,p=w.plannerTest,m=topicFixture();p.set({subjects:[{id:'a',name:'Direito',color:'#315fb3',contents:['Conteúdo novo','Questões','Resumo (Revisão)']}],stages:[]});p.configure({edital:{subjects:[m],plan:{}}});const plan=p.buildPlan(topicConfig(),[m]);p.newPlan('Tópicos',plan.stages,plan.config);let saved=JSON.parse(w.localStorage.getItem('ciclo-estudos-v1:cloud:actual-topics'));const theory=saved.stages.filter(s=>s.curriculum.phase==='theory');theory.forEach(s=>s.done=s.target);p.configure({stages:saved.stages});p.save();saved=JSON.parse(w.localStorage.getItem('ciclo-estudos-v1:cloud:actual-topics'));assert.equal(saved.edital.subjects[0].topics.find(t=>t.id==='new').done,true);const review=saved.stages.find(s=>s.curriculum.topicId==='new'&&s.curriculum.phase==='review');assert.equal(p.stageReady(review),false);for(const s of saved.stages.filter(s=>s.curriculum.phase==='theory'))s.curriculumCompletedOn=new Date(Date.now()-8*86400000).toISOString().slice(0,10);p.configure({stages:saved.stages});assert.equal(p.stageReady(review),true);const second=theory[1],entry={subjectId:'a',content:'Conteúdo novo',topic:second.curriculum.topicName,seconds:60,roundId:p.round()};p.configure({session:{stageId:second.id,elapsed:0,running:false,last:Date.now()}});p.assign(entry);assert.equal(entry.stageId,second.id);const backup=JSON.parse(w.localStorage.getItem('ciclo-estudos-v1:cloud:actual-topics'));assert.ok(p.validate({format:'ciclo-estudos-backup',version:1,data:backup}).stages.some(s=>s.curriculum));w.close();});
test('topic task curriculum includes video lessons and keeps all required followups',async()=>{const d=await boot({id:'task-topics'}),w=d.window,p=w.plannerTest;p.set({subjects:[{id:'a',name:'Direito',color:'#315fb3',contents:[]}],stages:[]});const plan=p.buildPlan({...topicConfig(),mode:'task',dailyTasks:2,weeklyTasks:14,taskActivities:[{unit:'páginas',quantity:10},{unit:'questões',quantity:20},{unit:'cartões',quantity:30}],videoTasks:{enabled:true,quantity:3,theoryShare:100}},[topicFixture()]);assert.ok(plan.stages.some(s=>s.curriculum.topicId==='new'&&s.content==='Videoaula'&&s.unit==='videoaulas'&&s.target===3));assert.ok(plan.stages.some(s=>s.curriculum.topicId==='known'&&s.content==='Questões'));assert.equal(plan.coverage.total,2);w.close();});

test('complete Receita Federal curriculum fits storage and survives backup validation',async()=>{const d=await boot({id:'full-rfb'}),w=d.window,p=w.plannerTest;p.createExam(p.examCatalog().find(e=>e.id==='rfb-auditor-2022'));const plan=p.buildPlan({...topicConfig(),topicHours:2,blockMinutes:25},p.edital().subjects);assert.ok(plan.coverage.total>400);assert.ok(plan.stages.length<=5000);const made=p.newPlan('Receita completa',plan.stages,plan.config);assert.ok(made,'Full curriculum must save within browser storage quota');const data=JSON.parse(w.localStorage.getItem('ciclo-estudos-v1:cloud:full-rfb'));assert.ok(p.validate({format:'ciclo-estudos-backup',version:1,data}).stages.length>1000);const stored=w.localStorage.getItem('ciclo-estudos-v1:cloud:full-rfb');w.eval(readFileSync('cloud-ui.js','utf8'));const full=p.validate({format:'ciclo-estudos-backup',version:1,data});const pending=w.cloudStateJSON(full);w.localStorage.setItem('ciclo-estudos-v1:cloud:full-rfb:sync',JSON.stringify({version:1,pending:{payload:JSON.parse(pending)}}));assert.equal(w.cloudHydrateState(JSON.parse(pending)).plannings[0].data.stages.length,full.stages.length);w.close();const loaded=await boot({id:'full-rfb'},stored);assert.ok(loaded.window.plannerTest.plans()[0].data.stages.length>1000);assert.equal(loaded.window.plannerTest.exams().find(e=>e.sourceId==='rfb-auditor-2022').data.subjects.length,17);loaded.window.close();});

test('calendar repeats only maintenance after the first topic pass and limits dated plans to before exam',async()=>{const d=await boot({id:'topic-repeat'}),w=d.window,p=w.plannerTest,m=topicFixture();p.set({subjects:[{id:'a',name:'Direito',color:'#315fb3',contents:[]}],stages:[]});p.configure({edital:{subjects:[m],plan:{}}});const plan=p.buildPlan(topicConfig(),[m]);p.newPlan('Conteúdo',plan.stages,plan.config);const end=new Date();end.setDate(end.getDate()+50);const projected=p.project(end),future=Object.values(projected).flat().filter(b=>b.round>0);assert.ok(future.length>0);const ids=new Set(plan.stages.filter(s=>s.curriculum.phase==='theory').map(s=>s.curriculum.key));const data=JSON.parse(w.localStorage.getItem('ciclo-estudos-v1:cloud:topic-repeat'));assert.ok(future.every(b=>!ids.has(data.stages.find(s=>s.id===b.stageId).curriculum.key)));for(const s of data.stages)s.done=s.target;p.configure({stages:data.stages});p.save();w.document.getElementById('finishCycle').click();const after=JSON.parse(w.localStorage.getItem('ciclo-estudos-v1:cloud:topic-repeat'));assert.ok(after.stages.every(s=>s.curriculum.phase!=='theory'));assert.equal(after.edital.plan.maintenance,true);w.close();});

test('edital edits planning and recorded hours are immediately queued and confirmed in database adapter',async()=>{const d=await boot({id:'cloud-every-change'},null,true),w=d.window,p=w.plannerTest,{cloud,writes}=w.testCloud;p.createExam(p.examCatalog().find(e=>e.id==='see-df'));await cloud.sync.flush();const m=p.edital().subjects[0];m.topics[0].done=true;p.save();await cloud.sync.flush();assert.equal(writes.at(-1).edital.subjects[0].topics[0].done,true);p.newPlan('Nuvem',[{subjectId:m.subjectId,content:'Conteúdo novo',target:1800,done:0}],topicConfig());await cloud.sync.flush();assert.equal(writes.at(-1).plannings.at(-1).name,'Nuvem');const h={id:'study-cloud',kind:'study',subjectId:m.subjectId,name:m.name,seconds:900,date:new Date().toISOString(),content:'Conteúdo novo',roundId:p.round()};p.configure({history:[h]});p.save();await cloud.sync.flush();assert.equal(writes.at(-1).history[0].seconds,900);assert.equal(cloud.sync.pending,null);assert.match(w.document.getElementById('cloudStatus').textContent,/Salvo na nuvem/);assert.match(w.document.getElementById('cloudStatus').title,/Supabase/);const original=w.Storage.prototype.setItem;w.Storage.prototype.setItem=()=>{throw new Error('quota')};m.topics[0].done=false;assert.equal(p.save(),true);await cloud.sync.flush();assert.equal(writes.at(-1).edital.subjects[0].topics[0].done,false);w.Storage.prototype.setItem=original;w.close();});

test('home planning checklist opens the planning wizard',async()=>{const d=await boot({id:'home-planning'}),w=d.window;w.plannerTest.set({subjects:[{id:'a',name:'Direito',color:'#315fb3',contents:[]}],stages:[]});w.plannerTest.configure({ui:{setupStarted:true,setupGoalsComplete:true}});w.document.querySelector('[data-tab="home"]').click();const button=w.document.getElementById('setupCycle');assert.equal(button.textContent,'Criar planejamento');button.click();assert.equal(w.document.getElementById('planningWizardDialog').open,true);assert.equal(w.document.getElementById('cycleDialog').open,false);w.close();});

test('Minhas Provas shows per-exam metrics and opens details without switching the active proof',async()=>{const d=await boot({id:'my-proofs'}),w=d.window,p=w.plannerTest,$=id=>w.document.getElementById(id);const see=p.createExam(p.examCatalog().find(e=>e.id==='see-df')),m=p.edital().subjects[0];p.configure({history:[{id:'study-see',kind:'study',subjectId:m.subjectId,name:m.name,content:'Questões',seconds:3600,correct:8,wrong:2,date:new Date().toISOString()}]});m.topics[0].done=true;p.save();const rf=p.createExam(p.examCatalog().find(e=>e.id==='rfb-auditor-2022'));const errors=[];w.addEventListener('error',e=>{errors.push(e.error?.stack||e.message);e.preventDefault()});w.document.querySelector('[data-tab="myexams"]').click();assert.deepEqual(errors,[]);assert.equal($('pageTitle').textContent,'Minhas Provas');assert.equal(w.document.querySelectorAll('.proof-card').length,2);w.document.querySelector('[data-proof-details="'+see.id+'"]').click();assert.deepEqual(errors,[]);assert.equal($('pageTitle').textContent,'Detalhes da prova');assert.match(w.document.querySelector('.proof-detail-summary').textContent,/1h 0min/);assert.match(w.document.querySelector('.proof-detail-summary').textContent,/80%/);assert.equal(p.edital().subjects.length,17);assert.equal($('sideExamSelect').value,rf.id);w.document.querySelector('[data-proof-subject="'+m.subjectId+'"]').click();assert.deepEqual(errors,[]);assert.ok(w.document.querySelector('.proof-topic-details'));$('proofSubjectSearch').value='zzzz';$('proofSubjectSearch').dispatchEvent(new w.Event('input'));assert.deepEqual(errors,[]);assert.match(w.document.querySelector('.proof-table').textContent,/Nenhuma matéria encontrada/);w.document.querySelector('[data-proof-go="edital"]').click();assert.deepEqual(errors,[]);assert.equal(p.edital().subjects.length,10);assert.equal($('sideExamSelect').value,see.id);assert.equal($('pageTitle').textContent,'Edital verticalizado');w.close();});

test('automatic planning times use routine domain and completed-topic study history',async()=>{const d=await boot({id:'auto-estimates'}),w=d.window,p=w.plannerTest,m=topicFixture();p.set({subjects:[{id:'a',name:'Direito',color:'#315fb3',contents:['Conteúdo novo']}],stages:[]});const config=topicConfig(),first=p.autoTimes(config,[m]);assert.equal(first.minimumMinutes,20);assert.ok(first.blockMinutes>=20&&first.blockMinutes<=50);assert.equal(first.estimationSources.a,'dominio');const beginner=p.autoTimes(config,[{...m,level:'beginner'}]);assert.ok(beginner.subjectTopicHours.a>first.subjectTopicHours.a);p.configure({history:[{id:'old',kind:'study',subjectId:'a',topic:'1.1 · Já estudado',content:'Conteúdo novo',seconds:2700,date:new Date().toISOString()}]});const observed=p.autoTimes(config,[m]);assert.equal(observed.subjectTopicHours.a,.75);assert.equal(observed.estimationSources.a,'historico');const plan=p.buildPlan({...config,...observed},[m]);const theory=plan.stages.filter(s=>s.curriculum.topicId==='new'&&s.curriculum.phase==='theory');assert.ok(theory.length>0);assert.ok(theory.reduce((n,s)=>n+s.target,0)>=.75*3600);w.close();});

test('activity migration renames existing records and snapshots without changing study totals',async()=>{const user={id:'activity-migration'},d=await boot(user),w=d.window,p=w.plannerTest;p.set({subjects:[{id:'a',name:'Direito',color:'#315fb3',contents:['Resumo (Revisão)','Anki (Revisão','Questões']}],stages:[]});p.newPlan('Anterior',[{subjectId:'a',content:'Resumo (Revisão)',target:1800,done:0}],topicConfig());p.configure({history:[{id:'old-study',kind:'study',subjectId:'a',name:'Direito',content:'Anki (Revisão)',category:'Anki / Flashcards',seconds:600,correct:3,wrong:1,date:new Date().toISOString()}]});p.save();const data=JSON.parse(w.localStorage.getItem('ciclo-estudos-v1:cloud:activity-migration'));delete data.activityNamesVersion;for(const e of data.exams)delete e.data.activityNamesVersion;const stored=JSON.stringify(data);w.close();const loaded=await boot(user,stored),v=loaded.window,after=JSON.parse(v.localStorage.getItem('ciclo-estudos-v1:cloud:activity-migration'));assert.deepEqual(after.subjects[0].contents,['Revisão','Resumo','Anki','Questões']);assert.equal(after.stages[0].content,'Resumo');assert.equal(after.plannings[0].data.stages[0].content,'Resumo');assert.equal(after.history[0].content,'Anki');assert.equal(after.history[0].seconds,600);assert.equal(after.history[0].correct,3);assert.equal(after.stages[0].done,0);v.document.querySelector('[data-tab="cycle"]').click();v.document.getElementById('editCycle').click();v.document.getElementById('addStage').click();assert.equal([...v.document.querySelectorAll('[data-content-choice]')].at(-1).value,'Revisão');v.close();});
test('topic plan interleaves new theory with practice from studied topics and rejects unknown review-only topics',async()=>{const d=await boot({id:'interleaved'}),w=d.window,p=w.plannerTest,m=topicFixture();p.set({subjects:[{id:'a',name:'Direito',color:'#315fb3',contents:['Revisão','Conteúdo novo','Questões']}],stages:[]});const plan=p.buildPlan(topicConfig(),[m]),byKey=new Map(plan.stages.map(s=>[s.curriculum.key,s]));const schedule=p.schedule(plan.stages,plan.config,{fresh:true}),first=Object.values(schedule.output).flat().slice(0,3).map(b=>byKey.get(b.stageId));assert.deepEqual(first.map(s=>s.curriculum.phase),['theory','review','questions']);assert.equal(first[0].curriculum.topicId,'new');assert.equal(first[1].curriculum.topicId,'known');assert.equal(first[2].curriculum.topicId,'known');assert.equal(first[1].content,'Revisão');assert.throws(()=>p.buildPlan(topicConfig(),[{...m,ratios:[0,50,50]}]),/ainda não estudados/);const known={...m,ratios:[0,50,50],topics:m.topics.map(t=>({...t,done:true}))};assert.ok(p.buildPlan(topicConfig(),[known]).stages.every(s=>s.curriculum.phase!=='theory'));w.close();});
test('planning switches between list and embedded calendar preserving stages progress and selection',async()=>{const user={id:'planning-views'},d=await boot(user),w=d.window,p=w.plannerTest;p.set({subjects:[{id:'a',name:'Direito',color:'#315fb3',contents:['Revisão']}],stages:[]});p.newPlan('Visualização',[{subjectId:'a',content:'Revisão',target:1800,done:0}],topicConfig());assert.ok(w.document.querySelector('.cycle-layout'));w.document.querySelector('[data-planning-display="calendar"]').click();assert.ok(w.document.getElementById('planningCalendarHost'));assert.equal(w.document.querySelector('.cycle-layout'),null);assert.ok(w.document.querySelector('.plan-week'));w.document.querySelector('[data-plan-view="day"]').click();assert.ok(w.document.querySelector('#planningCalendarHost .plan-daily'));let saved=JSON.parse(w.localStorage.getItem('ciclo-estudos-v1:cloud:planning-views'));assert.equal(saved.ui.planningDisplay,'calendar');assert.equal(saved.stages.length,1);assert.equal(saved.stages[0].done,0);w.document.querySelector('[data-planning-display="list"]').click();assert.ok(w.document.querySelector('.cycle-layout'));assert.equal(w.document.getElementById('cycleTotalsView').value,'analytic');w.close();});
